function collect_reject_history(frm, cdt, cdn) {
    const row = locals[cdt][cdn];
    if (!row) return;

    const request_id = row.request_id || null;
    if (!request_id) return;

    // Prepare entry
    const entry = {
        request_id: request_id,
        approval_status: row.approval_status || null,
        reason_for_rejection: row.reason_for_rejection || null,
        parent_child_row: row.name || null,
        parent_lead: frm.doc.name || null,
        created_by: frappe.session.user,
        date_and_time: frappe.datetime.now_datetime()
    };

    // Use request_id as key in buffer
    frm.__reject_history = frm.__reject_history || {};
    frm.__reject_history[request_id] = entry;

    frm.dirty();
}

// Attach triggers to both fields
frappe.ui.form.on("Lead Design Request Child Table", {
    approval_status: collect_reject_history,
    reason_for_rejection: collect_reject_history
});

// After Lead save, send all collected history to server
frappe.ui.form.on('Lead', {
    after_save: function(frm) {
        if (!frm.__reject_history || Object.keys(frm.__reject_history).length === 0) return;

        const payload = Object.values(frm.__reject_history);

        frappe.call({
            method: "impressio.impressio.doctype.lead.lead.create_reject_history_entries",
            args: {
                parent_doctype: frm.doc.doctype,
                parent_name: frm.doc.name,
                entries: payload
            },
            freeze: true,
            freeze_message: "Recording reject history...",
            callback: function(r) {
                if (!r.exc) {
                    frm.reload_doc();
                } else {
                    frappe.msgprint({
                        title: __('Error'),
                        message: __('Could not create reject history. Check server logs.'),
                        indicator: 'red'
                    });
                }
            }
        });

        frm.__reject_history = {};
    }
});



