frappe.ui.form.on("Lead", {
    refresh(frm) {
        update_view_buttons(frm);

        // Re-run when table refreshes (dynamic grid)
        frm.fields_dict["custom_design_request"].grid.wrapper.on("click", ".grid-row", function () {
            update_view_buttons(frm);
        });

        // Handle "View" button click → show previous PDF links
        frm.fields_dict["custom_design_request"].grid.wrapper.on("click", 'button[data-fieldname="view"]', function (e) {
            e.preventDefault();
            const idx = $(this).closest(".grid-row").attr("data-idx");
            const row = frm.doc.custom_design_request.find(r => String(r.idx) === String(idx));
            if (row) open_previous_pdfs_dialog(frm, row);
        });
    },
});

function update_view_buttons(frm) {
    setTimeout(() => {
        frm.fields_dict["custom_design_request"].grid.wrapper
            .find('button[data-fieldname="view"]')
            .each(function () {
                $(this).text("View");
            });
    }, 50);
}

/**
 * Helper: safely blur any element that would be hidden from AT (aria-hidden)
 * This prevents the "Blocked aria-hidden ... descendant retained focus" error.
 */
function safeBlurIfHiddenAncestorFocused() {
    try {
        const active = document.activeElement;
        if (!active) return;

        // If the active element is inside a modal-like element that is aria-hidden,
        // blur it so assistive tech doesn't remain focused on a hidden element.
        const modalAncestor = active.closest('.modal, [aria-hidden="true"]');
        if (modalAncestor) {
            const ariaHidden = modalAncestor.getAttribute && modalAncestor.getAttribute('aria-hidden');
            if (ariaHidden === 'true' || modalAncestor.classList.contains('modal')) {
                // blur the element — this will remove focus from the hidden element
                active.blur && active.blur();
                // as a fallback, shift focus to body
                try { document.body.focus(); } catch (e) {}
            }
        }
    } catch (e) {
        // don't break if anything goes wrong
        console.warn("safeBlurIfHiddenAncestorFocused error:", e);
    }
}

/**
 * Open dialog that lists previous PDFs for a row.
 * Reuses dialog instances per request_id/idx to avoid creating many modals.
 */
function open_previous_pdfs_dialog(frm, row) {
    // create a cache container on the form if not present
    frm._prev_pdfs_dialogs = frm._prev_pdfs_dialogs || {};

    // key for caching the dialog — prefer request_id, fallback to idx
    const key = row.request_id || `idx_${row.idx}`;

    // If a dialog exists for this key, reuse it and just update the content/title
    if (frm._prev_pdfs_dialogs[key]) {
        const cached = frm._prev_pdfs_dialogs[key];
        // update title
        try {
            if (cached.dialog && cached.dialog.set_title) {
                cached.dialog.set_title(`📜 Previous Design PDFs for ${row.request_id || "Design Request"}`);
            } else if (cached.dialog && cached.dialog.$title) {
                // safe fallback if set_title is not present
                cached.dialog.$title && cached.dialog.$title.text && cached.dialog.$title.text(`📜 Previous Design PDFs for ${row.request_id || "Design Request"}`);
            }
        } catch (e) { /* ignore title update errors */ }

        // update HTML content
        cached.render_pdf_links = cached.render_pdf_links || render_pdf_links_factory(cached.dialog);
        // parse potential in-row JSON and render immediately if available
        const pdf_links = extract_pdf_links_from_row(row);
        if (pdf_links && pdf_links.length > 0) {
            safeBlurIfHiddenAncestorFocused();
            cached.render_pdf_links(pdf_links);
            return;
        }

        // fallback to server fetch if cached row didn't have links
        safeBlurIfHiddenAncestorFocused();
        cached.dialog.set_value("pdf_links_html", "<p style='text-align:center;'>Loading previous PDFs...</p>");
        cached.dialog.show();

        // fetch from server
        fetch_previous_pdfs_from_server(row, cached.render_pdf_links, cached.dialog);
        return;
    }

    // If dialog doesn't exist, create it and cache it
    const dialog = new frappe.ui.Dialog({
        title: `📜 Previous Design PDFs for ${row.request_id || "Design Request"}`,
        size: "large",
        fields: [{ fieldtype: "HTML", fieldname: "pdf_links_html" }],
        primary_action_label: "Close",
        primary_action() {
            dialog.hide();
        },
    });

    // keep a reference to title jQuery element (some versions expose this)
    dialog.$title = dialog.wrapper && dialog.wrapper.find && dialog.wrapper.find('.modal-title');

    // factory that returns a render function bound to the dialog
    const render_pdf_links = render_pdf_links_factory(dialog);

    // cache it
    frm._prev_pdfs_dialogs[key] = {
        dialog: dialog,
        render_pdf_links: render_pdf_links,
    };

    // Try extracting links from the row first
    let pdf_links = extract_pdf_links_from_row(row);

    if (pdf_links && pdf_links.length > 0) {
        safeBlurIfHiddenAncestorFocused();
        render_pdf_links(pdf_links);
        return;
    }

    // No links in row; fetch from server
    safeBlurIfHiddenAncestorFocused();
    dialog.set_value("pdf_links_html", "<p style='text-align:center;'>Loading previous PDFs...</p>");
    dialog.show();

    fetch_previous_pdfs_from_server(row, render_pdf_links, dialog);
}

/**
 * Factory that returns a render function closed over a dialog instance.
 * Keeps rendering consistent and centralised.
 */
function render_pdf_links_factory(dialog) {
    return function render_pdf_links(links) {
        if (!links || links.length === 0) {
            dialog.set_value("pdf_links_html", "<p style='text-align:center;'>No previous PDFs found.</p>");
            dialog.show();
            return;
        }

        // Build friendly link list; sanitize quotes in URL
        const html = `
            <div style="padding:15px;">
                <ul style="list-style:none;padding:0;margin:0;">
                    ${links.map((link, i) => {
                        const safe = String(link).replace(/"/g, "%22");
                        return `
                            <li style="margin-bottom:10px;">
                                <a href="${safe}" target="_blank" rel="noopener noreferrer"
                                  style="color:#007bff;text-decoration:none;font-weight:500;">
                                  📄 PDF ${i + 1}: ${safe}
                                </a>
                            </li>
                        `;
                    }).join("")}
                </ul>
            </div>
        `;
        dialog.set_value("pdf_links_html", html);

        // ensure focus management — blur any leftover hidden-focused element,
        // and then show the dialog (which will move focus inside properly)
        safeBlurIfHiddenAncestorFocused();
        dialog.show();
    };
}

/**
 * Extract PDF links from the child row (handles strings, array, and JSON).
 * Returns an array of URLs (or empty array).
 */
function extract_pdf_links_from_row(row) {
    let pdf_links = [];
    if (row.view_images_json) {
        try {
            if (Array.isArray(row.view_images_json)) {
                pdf_links = row.view_images_json;
            } else if (typeof row.view_images_json === "string") {
                const parsed = JSON.parse(row.view_images_json);
                if (Array.isArray(parsed)) {
                    pdf_links = parsed.map(item => {
                        if (!item) return null;
                        if (typeof item === "string") return item;
                        return item.file_url || item.url || item.path || item.name || JSON.stringify(item);
                    }).filter(Boolean);
                }
            } else if (typeof row.view_images_json === "object") {
                // If stored directly as object/array by some clients
                if (Array.isArray(row.view_images_json)) {
                    pdf_links = row.view_images_json.map(i => (typeof i === "string" ? i : i.file_url || i.url)).filter(Boolean);
                }
            }
        } catch (err) {
            console.warn("Could not parse view_images_json:", err);
            pdf_links = [];
        }
    }
    return pdf_links;
}

/**
 * Fetch previous PDFs from the Design Request doc on server.
 * Expects: row.request_id to be present.
 * Calls render_fn with an array of pdf urls.
 */
function fetch_previous_pdfs_from_server(row, render_fn, dialog) {
    if (!row.request_id) {
        dialog && dialog.set_value && dialog.set_value("pdf_links_html", "<p style='text-align:center;'>No previous PDFs found (no request id).</p>");
        dialog && dialog.show && dialog.show();
        return;
    }

    frappe.call({
        method: "frappe.client.get",
        args: { doctype: "Design Request", name: row.request_id },
        callback: function (r) {
            try {
                if (!r.message) {
                    dialog.set_value("pdf_links_html", "<p style='text-align:center;'>No previous PDFs found.</p>");
                    dialog.show();
                    return;
                }

                const dr = r.message;
                const versions = dr.table_xqtk || [];

                // Gather PDF file paths from versions
                let links = versions.map(v => {
                    if (!v) return null;
                    if (v.data_link_for_ppt) return v.data_link_for_ppt;
                    if (v.file_url) return v.file_url;
                    if (v.url) return v.url;
                    return null;
                }).filter(Boolean);

                // Remove the last PDF (latest one)
                const prev_pdfs = links.slice(0, -1);

                render_fn(prev_pdfs);
            } catch (err) {
                console.error("Error fetching design request:", err);
                dialog.set_value("pdf_links_html", "<p style='text-align:center;'>Error loading previous PDFs.</p>");
                dialog.show();
            }
        },
        error: function (err) {
            console.error("frappe.call error:", err);
            dialog.set_value("pdf_links_html", "<p style='text-align:center;'>Could not load previous PDFs (server error).</p>");
            dialog.show();
        },
    });
}



