frappe.ui.form.on("Design Request", {
    refresh(frm) {
        // If Request ID is empty and document already has a name (naming series)
        if (!frm.doc.request_id && frm.doc.name && !frm.is_new()) {
            frm.set_value("request_id", frm.doc.name);
        }
    },

    after_save(frm) {
        // After saving, make sure Request ID matches the naming series
        if (frm.doc.request_id !== frm.doc.name) {
            frm.set_value("request_id", frm.doc.name);
            frm.save();
        }
    }
});

// Custom Script (Type = List) for DocType = "Lead"
frappe.listview_settings["Lead"] = {
  onload(listview) {

    const HIDE_LIST = ["Edit", "Clear Assignment", "Apply Assignment Rule", "Create Prospect"];

    function getActionsMenu() {
      if (listview.page && listview.page.actions_menu && listview.page.actions_menu.length) {
        return listview.page.actions_menu;
      }
      const $found = listview.page && listview.page.wrapper
        ? $(listview.page.wrapper).find('.actions .dropdown-menu, .page-actions .dropdown-menu')
        : $('.page-actions .dropdown-menu');
      return ($found && $found.length) ? $found : null;
    }

    function hideMenuItems($menu) {
      if (!$menu || !$menu.length) return;
      const selectors = 'a.dropdown-item, a, button, li > a, .dropdown-menu > li';
      $menu.find(selectors).each(function () {
        const $el = $(this);
        const text = ($el.text() || '').trim();
        if (!text) return;
        for (let want of HIDE_LIST) {
          if (text === want || text.indexOf(want) !== -1) {
            $el.closest('li, a, button').hide();
            break;
          }
        }
      });
    }

    const $menu = getActionsMenu();
    if ($menu) {
      hideMenuItems($menu);
    }

    const menuEl = $menu && $menu.get ? $menu.get(0) : null;
    if (menuEl) {
      const mo = new MutationObserver(() => {
        try { hideMenuItems($menu); } catch (e) { console.warn('hideMenuItems err', e); }
      });
      mo.observe(menuEl, { childList: true, subtree: true });
      try {
        if (listview.page && listview.page.on) {
          listview.page.on('hide', () => mo.disconnect());
        } else {
          setTimeout(() => mo.disconnect(), 30000);
        }
      } catch (e) { console.warn(e); }
    } else {
      let attempts = 0;
      const t = setInterval(() => {
        attempts++;
        const $m = getActionsMenu();
        if ($m) {
          hideMenuItems($m);
          const el = $m.get(0);
          const mo2 = new MutationObserver(() => hideMenuItems($m));
          mo2.observe(el, { childList: true, subtree: true });
          try { if (listview.page && listview.page.on) listview.page.on('hide', () => mo2.disconnect()); } catch(e){}
          clearInterval(t);
          return;
        }
        if (attempts > 10) clearInterval(t);
      }, 250);
    }

    // -------------------------
    // helper: perform frappe.call to bulk_qualify and THEN refresh listview
    // -------------------------
    function callBulkQualify(names) {
      frappe.call({
        method: "impressio.impressio.doctype.lead.lead.bulk_qualify",
        args: { docnames: JSON.stringify(names) },
        freeze: true,
        freeze_message: "Marking as Qualified...",
        callback: function (r) {
          // server-side exception
          if (!r) {
            frappe.show_alert({ message: "No response from server", indicator: "red" });
            return;
          }
          if (r.exc) {
            // r.exc often contains server trace — show friendly message and full trace in console
            frappe.msgprint({ title: 'Error', message: (r.exc || 'Unknown server error'), indicator: 'red' });
            console.error("bulk_qualify server exception:", r.exc);
            return;
          }

          const result = r.message || r;
          // result expected: { updated: [], skipped: [], failed: [] }
          const updated = (result.updated && result.updated.length) ? result.updated : [];
          const skipped = (result.skipped && result.skipped.length) ? result.skipped : [];
          const failed = (result.failed && result.failed.length) ? result.failed : [];

          // Build messages
          let summary = `<div style="margin-bottom:6px"><strong>Qualified:</strong> ${updated.length}</div>`;

          if (skipped.length) {
            // group skipped reasons
            const byReason = {};
            skipped.forEach(s => {
              const reason = s.reason || 'other';
              byReason[reason] = byReason[reason] || [];
              byReason[reason].push(s.name || s);
            });
            summary += `<div style="margin-bottom:6px"><strong>Skipped:</strong> ${skipped.length}</div>`;
            for (const reason in byReason) {
            //   summary += `<div style="margin-left:0px"><strong>${reason}:</strong> ${byReason[reason].slice(0,10).join(', ')}${byReason[reason].length>20? ' ...':''}</div>`;
            summary += `<div style="margin-left:0px"><strong>Skipped Lead ID:</strong> ${byReason[reason].slice(0,10).join(', ')}${byReason[reason].length>10? ' ...':''}</div>`;
            }
          }

          if (failed.length) {
            summary += `<div style="margin-top:8px"><strong style="color:#a00">Failed:</strong> ${failed.length}</div>`;
            // include first few failed details
            failed.slice(0,5).forEach(f => {
              const name = f.name || '(unknown)';
              const err = (f.error || f.message || JSON.stringify(f)).toString().slice(0,500);
              summary += `<div style="margin-left:8px"><code>${frappe.utils.escape_html(name)}</code>: ${frappe.utils.escape_html(err)}</div>`;
            });
            if (failed.length > 5) summary += `<div style="margin-left:8px">...and ${failed.length - 5} more</div>`;
          }

          // Success alert if at least one updated and no failures — otherwise info/warn
          if (updated.length && !failed.length) {
            frappe.show_alert({ message: `${updated.length} lead(s) marked as Qualified`, indicator: 'green' });
          } else if (updated.length && failed.length) {
            frappe.show_alert({ message: `${updated.length} updated, ${failed.length} failed`, indicator: 'orange' });
          } else if (!updated.length && (skipped.length || failed.length)) {
            frappe.show_alert({ message: `No leads updated`, indicator: 'orange' });
          } else {
            frappe.show_alert({ message: `No changes made`, indicator: 'blue' });
          }

          // Show a polished detail dialog so user can inspect skipped/failed rows.
        //   frappe.msgprint({
        //     title: 'Bulk Qualify Result',
        //     message: summary,
        //     indicator: failed.length ? 'red' : (skipped.length ? 'orange' : 'green')
        //   });
frappe.msgprint({
  title: 'Bulk Qualify Result',
  message: summary,
  indicator: failed.length ? 'red' : (skipped.length ? 'orange' : 'green'),
  // adds a prominent button that runs location.reload()
  primary_action: {
    label: 'Confirm',
    action: function() {
      // Close the dialog then reload
      // some versions of msgprint provide dialog param; safe to just reload
      location.reload();
    }
  },
  // optional secondary action (Close)
//   secondary_action: {
//     label: 'Close',
//     action: function() {
//       // close the message dialog by hiding the last opened dialog
//       // frappe.msgprint returns a dialog only in some versions, so try both ways
//       try {
//         // if a dialog reference exists on frappe.msgprint, hide it
//         if (frappe.msgprint && frappe.msgprint.dialog) {
//           frappe.msgprint.dialog.hide();
//         } else if (cur_dialog) {
//           cur_dialog.hide();
//         }
//       } catch (e) {
//         // fallback: do nothing
//       }
//     }
//   }
});


          // finally refresh the listview so statuses are visible
          try {
            // small timeout so DB commit is surely visible
            setTimeout(() => {
              if (listview && typeof listview.refresh === 'function') {
                listview.refresh();
              } else {
                location.reload();
              }
            }, 300);
          } catch (e) {
            console.warn('refresh failed, reloading', e);
            location.reload();
          }
        },
        error: function(xhr, status, err) {
          frappe.msgprint({ title: 'Error', message: `Request failed: ${err || status}`, indicator: 'red' });
        }
      });
    }

    // -------------------------
    // Add Qualified action (native, fast)
    // -------------------------
    listview.page.add_action_item("Qualified", () => {
      let selected = [];
      try {
        selected = (listview.get_checked_items && typeof listview.get_checked_items === 'function') ? listview.get_checked_items() : [];
      } catch (e) {
        selected = [];
      }

      const names = (selected || []).map(d => {
        if (typeof d === 'string') return d;
        if (d && d.name) return d.name;
        if (d && d.docname) return d.docname;
        if (Array.isArray(d) && d[0]) return d[0];
        return null;
      }).filter(Boolean);

      if (!names.length) {
        frappe.msgprint("Please select at least one Lead.");
        return;
      }

      try {
        frappe.confirm(
          `Are you sure you want to qualify selected lead(s)?`,
          () => {
            // on ok
            callBulkQualify(names);
            // no immediate location.reload() — the call will refresh the listview
          },
          () => {
            // on cancel — nothing
          }
        );
      } catch (e) {
        if (window.confirm(`Are you sure you want to qualify selected lead(s)?`)) {
          callBulkQualify(names);
        }
      }
    });

  } // onload
};









